// =============================================================================
// tb_ntt_top.v - System-level testbench of ntt_axil_top through AXI4-Lite
//
//   For every test vector v (generated by model/ntt_golden.py):
//     T1  load x            -> NTT  -> compare with ntt_exp[v]   (golden model)
//     T2  (in place)        -> INTT -> compare with x            (round trip)
//     T3  load x            -> INTT -> compare with intt_exp[v]  (golden model)
//   Plus directed checks: ID/PARAM registers, input reduction (>= q),
//   SLVERR on coefficient access while busy, IRQ / W1C DONE.
//
//   Plusargs:  +NVEC=<n>   number of vectors to run (default: all in file)
//   Defines :  +define+GATE_SIM  (gate-level netlist)   +define+DUMP_VCD
// =============================================================================
`timescale 1ns/1ps
module tb_ntt_top;
    localparam N        = 256;
    localparam Q        = 3329;
    localparam MAXVEC   = 1000;
    localparam CLK_HALF = 5;          // 100 MHz in simulation

    localparam A_CTRL   = 12'h000,
               A_STATUS = 12'h004,
               A_CYCLES = 12'h008,
               A_ID     = 12'h00C,
               A_PARAM  = 12'h010,
               A_COEFF  = 12'h400;

    // ------------------------------------------------------------------------
    // DUT
    // ------------------------------------------------------------------------
    reg         clk = 1'b0;
    reg         rst_n = 1'b0;
    reg  [11:0] awaddr = 0;  reg awvalid = 0;  wire awready;
    reg  [31:0] wdata  = 0;  reg [3:0] wstrb = 4'hF; reg wvalid = 0; wire wready;
    wire [1:0]  bresp;       wire bvalid;      reg bready = 0;
    reg  [11:0] araddr = 0;  reg arvalid = 0;  wire arready;
    wire [31:0] rdata;       wire [1:0] rresp; wire rvalid; reg rready = 0;
    wire        irq;

    always #CLK_HALF clk = ~clk;

    ntt_axil_top dut (
        .s_axi_aclk    (clk),     .s_axi_aresetn (rst_n),
        .s_axi_awaddr  (awaddr),  .s_axi_awprot  (3'b000),
        .s_axi_awvalid (awvalid), .s_axi_awready (awready),
        .s_axi_wdata   (wdata),   .s_axi_wstrb   (wstrb),
        .s_axi_wvalid  (wvalid),  .s_axi_wready  (wready),
        .s_axi_bresp   (bresp),   .s_axi_bvalid  (bvalid),  .s_axi_bready (bready),
        .s_axi_araddr  (araddr),  .s_axi_arprot  (3'b000),
        .s_axi_arvalid (arvalid), .s_axi_arready (arready),
        .s_axi_rdata   (rdata),   .s_axi_rresp   (rresp),
        .s_axi_rvalid  (rvalid),  .s_axi_rready  (rready),
        .irq           (irq)
    );

`ifdef GATE_SIM
    initial begin
        `ifdef SDF_FILE
            $sdf_annotate(`SDF_FILE, dut);
        `endif
    end
`endif

`ifdef DUMP_VCD
    initial begin
        $dumpfile("ntt_top.vcd");
        $dumpvars(0, tb_ntt_top);
    end
`endif

    // ------------------------------------------------------------------------
    // AXI4-Lite master tasks
    // ------------------------------------------------------------------------
    reg [1:0]  last_resp;
    reg [31:0] rd_val;

    task axi_write(input [11:0] addr, input [31:0] data);
        begin
            @(negedge clk);
            awaddr = addr; wdata = data; awvalid = 1'b1; wvalid = 1'b1;
            @(posedge clk);
            while (!awready) @(posedge clk);
            @(negedge clk);
            awvalid = 1'b0; wvalid = 1'b0; bready = 1'b1;
            @(posedge clk);
            while (!bvalid) @(posedge clk);
            last_resp = bresp;
            @(negedge clk);
            bready = 1'b0;
        end
    endtask

    task axi_read(input [11:0] addr);
        begin
            @(negedge clk);
            araddr = addr; arvalid = 1'b1;
            @(posedge clk);
            while (!arready) @(posedge clk);
            @(negedge clk);
            arvalid = 1'b0; rready = 1'b1;
            @(posedge clk);
            while (!rvalid) @(posedge clk);
            rd_val = rdata; last_resp = rresp;
            @(negedge clk);
            rready = 1'b0;
        end
    endtask

    // ------------------------------------------------------------------------
    // Test data
    // ------------------------------------------------------------------------
    reg [11:0] vin   [0:MAXVEC*N-1];
    reg [11:0] vntt  [0:MAXVEC*N-1];
    reg [11:0] vintt [0:MAXVEC*N-1];

    integer errors, nvec, v, i, timeout, fd, rc;
    integer cyc_ntt, cyc_intt;
    integer t_pass, t_fail;
    reg     vec_ok;

    task load_poly(input integer vec);
        begin
            for (i = 0; i < N; i = i + 1)
                axi_write(A_COEFF + 4*i, {20'd0, vin[vec*N + i]});
        end
    endtask

    // which: 0 = ntt_exp, 1 = input (round trip), 2 = intt_exp
    task check_poly(input integer vec, input integer which, input [8*12-1:0] name);
        reg [11:0] exp;
        integer nerr;
        begin
            nerr = 0;
            for (i = 0; i < N; i = i + 1) begin
                axi_read(A_COEFF + 4*i);
                case (which)
                    0: exp = vntt [vec*N + i];
                    1: exp = vin  [vec*N + i];
                    default: exp = vintt[vec*N + i];
                endcase
                if (rd_val[11:0] !== exp) begin
                    nerr = nerr + 1;
                    if (errors + nerr < 20)
                        $display("[FAIL] vec %0d %0s coeff[%0d] = %0d, expected %0d",
                                 vec, name, i, rd_val[11:0], exp);
                end
            end
            if (nerr == 0) t_pass = t_pass + 1;
            else begin t_fail = t_fail + 1; vec_ok = 1'b0; end
            errors = errors + nerr;
        end
    endtask

    // start operation (mode 0 = NTT, 1 = INTT), wait for IRQ, return cycles
    task run_op(input integer intt, output integer cycles);
        begin
            axi_write(A_CTRL, {29'd0, 1'b1, intt[0], 1'b1});   // IRQ_EN | MODE | START
            timeout = 0;
            while (!irq && timeout < 10000) begin @(posedge clk); timeout = timeout + 1; end
            if (!irq) begin
                $display("[FAIL] timeout waiting for done (mode %0d)", intt);
                errors = errors + 1;
            end
            axi_read(A_CYCLES);  cycles = rd_val;
            axi_write(A_STATUS, 32'h2);                         // W1C DONE
        end
    endtask

    // ------------------------------------------------------------------------
    // Main
    // ------------------------------------------------------------------------
    initial begin
        errors = 0; t_pass = 0; t_fail = 0;
        $readmemh("vectors/ntt_in.hex",   vin);
        $readmemh("vectors/ntt_exp.hex",  vntt);
        $readmemh("vectors/intt_exp.hex", vintt);
        nvec = 100;
        fd = $fopen("vectors/nvec.txt", "r");
        if (fd != 0) begin
            rc = $fscanf(fd, "%d", nvec);
            $fclose(fd);
        end
        if ($value$plusargs("NVEC=%d", i)) nvec = i;
        if (nvec > MAXVEC) nvec = MAXVEC;

        repeat (5) @(posedge clk);
        rst_n = 1'b1;
        repeat (2) @(posedge clk);

        // ---------------- directed register tests ---------------------------
        axi_read(A_ID);
        if (rd_val !== 32'h4E545401) begin $display("[FAIL] ID = %h", rd_val); errors = errors + 1; end
        axi_read(A_PARAM);
        if (rd_val !== {16'd256, 16'd3329}) begin $display("[FAIL] PARAM = %h", rd_val); errors = errors + 1; end

        axi_write(A_COEFF + 4*7, 32'd4000);                    // >= q -> 4000-3329 = 671
        axi_read (A_COEFF + 4*7);
        if (rd_val[11:0] !== 12'd671) begin
            $display("[FAIL] input reduction: got %0d, expected 671", rd_val[11:0]); errors = errors + 1;
        end else $display("[PASS] register map + input reduction");

        // SLVERR while busy
        axi_write(A_CTRL, 32'h1);                               // NTT on garbage, no IRQ
        axi_write(A_COEFF, 32'd5);
        if (last_resp !== 2'b10) begin $display("[FAIL] no SLVERR on write while busy"); errors = errors + 1; end
        axi_read(A_COEFF);
        if (last_resp !== 2'b10) begin $display("[FAIL] no SLVERR on read while busy"); errors = errors + 1; end
        axi_read(A_STATUS);
        if (rd_val[0] !== 1'b1) begin $display("[FAIL] BUSY not set"); errors = errors + 1; end
        timeout = 0;
        rd_val = 1;
        while (rd_val[0] && timeout < 3000) begin axi_read(A_STATUS); timeout = timeout + 1; end
        if (rd_val[1] !== 1'b1) begin $display("[FAIL] DONE not set"); errors = errors + 1; end
        axi_write(A_STATUS, 32'h2);
        axi_read(A_STATUS);
        if (rd_val[1] !== 1'b0) begin $display("[FAIL] DONE not cleared by W1C"); errors = errors + 1; end
        else if (errors == 0) $display("[PASS] busy protection (SLVERR) + DONE/W1C");

        // ---------------- vector tests ---------------------------------------
        $display("[INFO] running %0d vectors (NTT, round-trip INTT, INTT) ...", nvec);
        for (v = 0; v < nvec; v = v + 1) begin
            vec_ok = 1'b1;
            load_poly(v);
            run_op(0, cyc_ntt);
            check_poly(v, 0, "NTT");
            run_op(1, cyc_intt);
            check_poly(v, 1, "ROUNDTRIP");
            load_poly(v);
            run_op(1, cyc_intt);
            check_poly(v, 2, "INTT");
            if (v < 6 || (v % 20) == 0)
                $display("[INFO] vec %0d : %0s  (NTT %0d cycles, INTT %0d cycles)",
                         v, vec_ok ? "OK" : "FAIL", cyc_ntt, cyc_intt);
        end

        $display("==============================================================");
        $display(" Vectors           : %0d", nvec);
        $display(" Sub-tests passed  : %0d / %0d", t_pass, t_pass + t_fail);
        $display(" NTT  latency      : %0d cycles", cyc_ntt);
        $display(" INTT latency      : %0d cycles", cyc_intt);
        if (errors == 0) $display(" RESULT            : *** ALL TESTS PASSED ***");
        else             $display(" RESULT            : *** %0d ERRORS ***", errors);
        $display("==============================================================");
        $finish;
    end
endmodule
